INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-008','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'DRAG','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"DRAG","prompt":"按系统逐次高亮的目标框，将12个圆片图标拖入对应区域。","assessment_point":"连续触控拖拽与动作节奏","sub_dimension":"分拣操作","presentation_way":"屏幕任务","interaction_type":"连续定向拖拽","materials":"两侧目标框轮流高亮；圆片大小一致，避免分类负荷。","standard_instruction":"“每次把圆片拖到亮起来的框里。”","correct_response":"至少11次正确；无扫动或多指乱触。","scoring_points":"连续拖拽准确率、节奏、错误后修正。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"轨迹、离手、误触、反应时间。","evidence_type":"软件行为任务","validity_boundary":"不再测大小分类，只测连续触控操作。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"COG-R092/FM-R043","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
