INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-010','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'SOFTWARE_TASK','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"SOFTWARE_TASK","prompt":"一只手持续按住固定区，另一只手将5个图形依次拖到目标区；中途交换双手一次。","assessment_point":"双手触控协调与任务转换","sub_dimension":"双手转换","presentation_way":"屏幕多点触控","interaction_type":"双手同时操作","materials":"支持多点触控的平板；左右固定区、拖拽物、目标区。","standard_instruction":"“一只手按住圆点，另一只手把图形拖过去；看到换手提示后交换。”","correct_response":"固定触点保持；至少4个拖拽成功；能按提示换手。","scoring_points":"双手同时控制、换手、掉点和误触。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"固定中断次数、拖拽成功、换手反应时间。","evidence_type":"软件行为任务","validity_boundary":"仅适用于支持多点触控的设备；不代表真实物品传递能力。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"FM-R050/FM-08","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
