INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-FM-012','SUPERMARKET_SHELVER','BASE_ABILITY','FINE_MOTOR',NULL,'OFFLINE_OPERATION','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"OFFLINE_OPERATION","prompt":"双手端空托盘沿3米标线行走并放到指定台面。","assessment_point":"持物稳定、动态平衡与放置控制","sub_dimension":"持物稳定与移动","presentation_way":"实物操作","interaction_type":"持物稳定移动","materials":"共用低成本器材：轻质托盘、3个塑料空杯、地面标线。","standard_instruction":"“请双手端托盘，沿线走到另一边，放在标记位置。”","correct_response":"安全完成；托盘基本保持水平；杯子未掉落。","scoring_points":"持物稳定、行走安全、放置控制。","allowed_support":"可重复完整指令1次；允许日常辅具；材料位置按标准模板摆放；不示范关键动作，不进行手把手协助。","termination_condition":"出现疼痛、明显疲劳、吞咽/夹伤/跌落风险时立即终止并记录NR或ST。","system_log_indicators":"掉落、明显倾斜、用时、停顿、提示。","evidence_type":"直接动作表现","validity_boundary":"软件无法测量真实持物稳定、步态和动态平衡。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"FM-R049/FM-02","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
