INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-EMO-014','SUPERMARKET_SHELVER','BASE_ABILITY','EMOTION_REGULATION',NULL,'SOFTWARE_TASK','OBSERVATION_ONLY',3,'{"schema_version":"question-content-v1.2","question_type":"SOFTWARE_TASK","prompt":"综合记录评估过程中自然出现的轻度困难后，是否表达需要、使用支持并恢复或完成交接。","assessment_point":"情绪波动后恢复基本沟通并完成安全交接","sub_dimension":"恢复与交接","presentation_way":"系统嵌入观察","interaction_type":"跨任务恢复指标","materials":"从其他任务自动提取事件，不额外诱发情绪。","standard_instruction":"不单独追加诱发任务；测评员仅按统一规则记录。","correct_response":"出现困难时有功能性表达或策略；在支持后返回、结束或交接。","scoring_points":"表达、支持使用、恢复/交接结果。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"事件数、策略、恢复时间、支持等级。","evidence_type":"嵌入式行为观察","validity_boundary":"不是独立题目，不应与具体情境题重复加权计分。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"NEW-EMO-自然观察","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"},"notes":"建议报告为观察指标，不计入简单题目总数或单独低权重呈现。"}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
