INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SOC-005','SUPERMARKET_SHELVER','BASE_ABILITY','BASIC_SOCIAL',NULL,'SOFTWARE_TASK','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"SOFTWARE_TASK","prompt":"系统生成完成、部分完成或受阻三种真实状态之一，受测者向虚拟负责人汇报。","assessment_point":"向负责人报告完成、未完成或遇到问题","sub_dimension":"任务状态汇报","presentation_way":"屏幕任务","interaction_type":"状态汇报","materials":"任务结果与消息选项动态匹配。","standard_instruction":"“请把现在的实际情况告诉负责人。”","correct_response":"汇报与实际状态一致，并指出未完成部分（如有）。","scoring_points":"真实性、完整性、对象。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"消息内容、遗漏、时延。","evidence_type":"软件行为任务","validity_boundary":"不要求长句或礼貌修饰，重点是有效信息。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"NEW-SOC-状态汇报","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
