INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SOC-007','SUPERMARKET_SHELVER','BASE_ABILITY','BASIC_SOCIAL',NULL,'SINGLE_CHOICE','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"SINGLE_CHOICE","prompt":"图片呈现无意碰落他人物品，受测者从动作卡中组合“停止—说明/道歉—协助恢复”。","assessment_point":"发生轻微影响他人的意外后进行沟通和修复","sub_dimension":"意外后的修复","presentation_way":"屏幕分支情境","interaction_type":"意外后的修复","materials":"中性图示；不使用羞辱性语言。","standard_instruction":"“发生这个意外后，你会怎么处理？”","correct_response":"选择或表达至少包含说明和协助恢复的功能性处理。","scoring_points":"承担信息、修复行动、是否求助。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"步骤选择、顺序、时延。","evidence_type":"情境判断任务","validity_boundary":"仍包含社会知识成分，不能单独证明真实情境行为。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"SOC-R241","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SOC-008','SUPERMARKET_SHELVER','BASE_ABILITY','BASIC_SOCIAL',NULL,'SOFTWARE_TASK','SCORED_ITEM',1,'{"schema_version":"question-content-v1.2","question_type":"SOFTWARE_TASK","prompt":"与虚拟同伴轮流放置图块，共同完成6步图案。","assessment_point":"在明确规则下进行轮流合作","sub_dimension":"轮流互动","presentation_way":"屏幕互动","interaction_type":"虚拟轮流协作","materials":"对方回合时间随机；不锁死受测者操作。","standard_instruction":"“轮到你时放一块，完成后等对方。”","correct_response":"在本人回合操作并保持共同目标。","scoring_points":"轮流、等待、任务正确。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"抢先、漏轮、反应时间、正确率。","evidence_type":"软件行为任务","validity_boundary":"不能完全替代真实双人互动，但可标准化轮流规则。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"SOC-R226/RULE-R149","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SOC-009','SUPERMARKET_SHELVER','BASE_ABILITY','BASIC_SOCIAL',NULL,'SOFTWARE_TASK','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"SOFTWARE_TASK","prompt":"与虚拟同伴分工完成8件材料整理，中途按提示交换角色。","assessment_point":"在简单分工中与他人协同完成共同目标","sub_dimension":"协作分工","presentation_way":"屏幕互动","interaction_type":"虚拟分工协作","materials":"一个角色取物、一个角色摆放；虚拟同伴按脚本行动。","standard_instruction":"“按分工完成任务，看到交换提示后换角色。”","correct_response":"完成本人任务；能等待对方信息并换角色。","scoring_points":"分工保持、信息依赖、换角色。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"越界操作、等待、换角色时延。","evidence_type":"软件行为任务","validity_boundary":"虚拟协作不能测真实协商能力，主要测分工规则。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"SOC-R242","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SOC-010','SUPERMARKET_SHELVER','BASE_ABILITY','BASIC_SOCIAL',NULL,'SINGLE_CHOICE','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"SINGLE_CHOICE","prompt":"虚拟陌生人要求使用带需授权标识的工具，受测者表达拒绝并选择报告对象。","assessment_point":"对不安全或超出授权的请求作出拒绝并寻求帮助","sub_dimension":"拒绝与安全边界","presentation_way":"屏幕分支情境","interaction_type":"拒绝+报告","materials":"拒绝/AAC消息和负责人选择。","standard_instruction":"“对方让你做未经允许的事时，请处理。”","correct_response":"不执行；表达不能做/需确认；向正确对象报告。","scoring_points":"边界、拒绝、报告对象。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"工具点击、消息、报告时延。","evidence_type":"软件行为任务","validity_boundary":"授权规则需由学校统一，避免把顺从当作社交能力。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"NEW-SOC-安全拒绝","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,0,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
