INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SAFE-008','SUPERMARKET_SHELVER','BASE_ABILITY','SAFETY_OPERATION',NULL,'OFFLINE_OPERATION','SCORED_ITEM',2,'{"schema_version":"question-content-v1.2","question_type":"OFFLINE_OPERATION","prompt":"从膝盖高度平台将轻质空箱搬到3米外平台。","assessment_point":"使用稳定、不过度弯腰的方式搬运轻箱","sub_dimension":"轻物搬运姿势","presentation_way":"实物操作","interaction_type":"轻箱搬运","materials":"学校常用空纸箱或塑料箱，重量统一且轻；两平台。","standard_instruction":"“请把这个轻箱安全搬到另一边。”","correct_response":"先观察路线；稳定抓持；避免扭转和遮挡视线；安全放置。","scoring_points":"路线、抓持、躯干控制、放置。","allowed_support":"可重复完整指令1次；允许日常辅具；材料位置按标准模板摆放；不示范关键动作，不进行手把手协助。","termination_condition":"出现疼痛、明显疲劳、吞咽/夹伤/跌落风险时立即终止并记录NR或ST。","system_log_indicators":"用时、停顿、视线遮挡、失稳、提示。","evidence_type":"直接动作表现","validity_boundary":"只能评估轻物搬运基础，不能外推到负重岗位能力。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"SAFE-R266/SAFE-R283","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"},"notes":"箱体尺寸、重量和可接受动作需康复/安全人员确认。"}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,1,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
