INSERT INTO question_bank(question_id,job_code,bank_domain,module_type,job_module_code,question_type,item_usage,difficulty_level,content_json,scoring_rule_json,media_asset_id,tool_asset_ids_json,safety_sensitive,sensory_tags_json,status,version) VALUES('GA-SAFE-014','SUPERMARKET_SHELVER','BASE_ABILITY','SAFETY_OPERATION',NULL,'SOFTWARE_TASK','SCORED_ITEM',3,'{"schema_version":"question-content-v1.2","question_type":"SOFTWARE_TASK","prompt":"在数字任务中随机出现已预告的紧急停止提示，停止操作并按系统路线选择撤离/报告。","assessment_point":"接到明确紧急停止指令后停止、放下材料并跟随指引","sub_dimension":"紧急停止与撤离","presentation_way":"屏幕模拟","interaction_type":"紧急停止流程","materials":"停止提示、虚拟路线、集合点/负责人。","standard_instruction":"“出现紧急停止提示时，停止任务并按指引操作。”","correct_response":"立即停止数字操作；选择正确路线和报告对象。","scoring_points":"停止反应、路线、报告。","allowed_support":"可重复完整指令1次；允许触控笔、日常视觉/听觉辅具及AAC；可调整非关键字体大小和音量；不得提示关键答案或替受测者完成操作。","termination_condition":"出现明显不适、持续挫败或设备故障时暂停；记录已完成步骤，不因设备问题记0分。","system_log_indicators":"停止时延、路线选择、错误触控。","evidence_type":"软件行为任务","validity_boundary":"不能替代学校真实消防/应急演练。","source":{"import_batch_id":"batch_base_ability_v02","source_file":"通用基础能力正式测评候选题库_v0.2-软件优先版.xlsx","source_trace":"EMO-R160/SAFE-应急","imported_at":"2026-07-11T13:54:30.118Z","imported_by":"seed-base-ability-v02"}}','{"scoring_type":"NO_SCORE","scoring_mode":"NONE"}',NULL,NULL,1,NULL,'DRAFT',1) ON CONFLICT(question_id) DO UPDATE SET module_type=excluded.module_type,question_type=excluded.question_type, item_usage=excluded.item_usage,difficulty_level=excluded.difficulty_level, content_json=excluded.content_json,scoring_rule_json=excluded.scoring_rule_json, safety_sensitive=excluded.safety_sensitive,status=excluded.status, updated_at=datetime('now');
